mapper.select:
/* DailyEntryMapper.selectEntryRequestId */
SELECT CONCAT('ER', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'DAILY_ENTRY_REQ'))
FROM DUAL

/* DailyEntryMapper.selectTodayRejectedCnt */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_DAILY_ENTRY_REQUEST
     WHERE CMPNY_CD   = #{cmpnyCd}
       AND USER_CD    = #{userCd}
       AND REQ_STATUS = '03'
       AND PROC_DTIME  >=  CURDATE()
       AND PROC_DTIME  <  DATE_ADD(CURDATE(), INTERVAL 1 DAY)
     LIMIT 1
) T

mapper.insert:
/* DailyEntryMapper.insertEntryRequest */
INSERT INTO TB_DAILY_ENTRY_REQUEST (
    CMPNY_CD
    , REQ_ID
    , SITE_CD
    , USER_CD
    , REQ_TYPE
    , REQ_STATUS
    , REQ_DTIME
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
    #{cmpnyCd}
    , #{reqId}
    , #{siteCd}
    , #{userCd}
    , #{reqType}
    , '01'
    , NOW()
    , #{userCd}
    , NOW()
)

mapper.update:
/* DailyEntryMapper.updateEntryRequestApprove */
UPDATE TB_DAILY_ENTRY_REQUEST
SET REQ_STATUS     = '02'
    , PROC_USER_CD = #{procUserCd}
    , PROC_DTIME   = NOW()
    , UPDATE_NO    = #{procUserCd}
    , UPDATE_DATE  = NOW()
WHERE CMPNY_CD   = #{cmpnyCd}
  AND REQ_ID     = #{reqId}
  AND REQ_STATUS = '01'

/* DailyEntryMapper.updateEntryRequestReject */
UPDATE TB_DAILY_ENTRY_REQUEST
SET REQ_STATUS      = '03'
    , REJECT_REASON = #{reason}
    , PROC_USER_CD  = #{procUserCd}
    , PROC_DTIME    = NOW()
    , UPDATE_NO     = #{procUserCd}
    , UPDATE_DATE   = NOW()
WHERE CMPNY_CD   = #{cmpnyCd}
  AND REQ_ID     = #{reqId}
  AND REQ_STATUS = '01'

/* DailyEntryMapper.updateEntryRequestConsume */
UPDATE TB_DAILY_ENTRY_REQUEST
SET REQ_STATUS      = '05'
    , CONSUME_DTIME = NOW()
    , UPDATE_NO     = #{userCd}
    , UPDATE_DATE   = NOW()
WHERE CMPNY_CD   = #{cmpnyCd}
  AND REQ_ID     = #{reqId}
  AND REQ_STATUS = '02'
  AND REQ_DTIME  >=  CURDATE()

mapper.select:
/* DailyEntryMapper.selectEntryRequestList */ SELECT R.REQ_ID AS reqId , R.SITE_CD AS siteCd , R.USER_CD AS userCd , D.USER_NM AS userNm , D.MBL_NO_LAST4 AS mblNoLast4 , D.MBL_NO_ENC AS mblNoEnc , R.REQ_TYPE AS reqType , R.REQ_STATUS AS reqStatus , DATE_FORMAT(R.REQ_DTIME, '%Y-%m-%d %H:%i') AS reqDtime , R.PROC_USER_CD AS procUserCd , P.USER_NM AS procUserNm , DATE_FORMAT(R.PROC_DTIME, '%Y-%m-%d %H:%i') AS procDtime , R.REJECT_REASON AS rejectReason FROM TB_DAILY_ENTRY_REQUEST R LEFT JOIN TB_DAILY_USER D ON ( R.CMPNY_CD = D.CMPNY_CD AND R.USER_CD = D.USER_CD ) LEFT JOIN TB_USER P ON ( R.CMPNY_CD = P.CMPNY_CD AND R.PROC_USER_CD = P.USER_CD ) WHERE R.CMPNY_CD = #{cmpnyCd} AND R.SITE_CD = #{siteCd}
AND R.REQ_STATUS = #{reqStatus}
AND R.REQ_TYPE = #{reqType}
AND R.REQ_DTIME >= STR_TO_DATE(#{reqDate}, '%Y%m%d') AND R.REQ_DTIME < DATE_ADD(STR_TO_DATE(#{reqDate}, '%Y%m%d'), INTERVAL 1 DAY)
ORDER BY R.REQ_DTIME DESC LIMIT #{limitCnt}

/* DailyEntryMapper.selectSiteAuthCnt */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_USER_SITE_AUTH
     WHERE CMPNY_CD = #{cmpnyCd}
       AND USER_CD  = #{userCd}
       AND SITE_CD  = #{siteCd}
       AND USE_YN   = 'Y'
     LIMIT 1
) T

/* DailyEntryMapper.selectSiteEntryAdmins */
SELECT DISTINCT U.USER_CD
  FROM TB_USER U
       INNER JOIN TB_USER_SITE_AUTH SA
          ON  U.CMPNY_CD = SA.CMPNY_CD
          AND U.USER_CD  = SA.USER_CD
          AND SA.SITE_CD = #{siteCd}
          AND SA.USE_YN  = 'Y'
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.USE_YN   = 'Y'
   AND U.ACCOUNT_STATUS = '01'
   AND U.AUTH_CD IN

           #{authCd}

mapper.insert:
/* DailyEntryMapper.insertEntryNotiOutbox */
INSERT INTO TB_NOTI_OUTBOX
(
    NOTI_ID
  , CMPNY_CD
  , SITE_CD
  , TARGET_USER_CD
  , NOTI_TYPE
  , CHANNEL
  , TITLE
  , BODY
  , DATA_PAYLOAD
  , SEND_STATUS
  , RETRY_CNT
  , DEDUP_KEY
  , DEL_YN
  , INSERT_NO
  , INSERT_DATE
)
VALUES
(
    (SELECT CONCAT(
        'N'
      , DATE_FORMAT(NOW(), '%Y%m%d')
      , LPAD(
            IFNULL(
                MAX(CAST(SUBSTR(T.NOTI_ID, 10, 3) AS UNSIGNED))
              , 0
            ) + 1
          , 3, '0'
        )
    ) FROM TB_NOTI_OUTBOX T
      WHERE T.CMPNY_CD = #{cmpnyCd}
        AND T.NOTI_ID LIKE CONCAT('N', DATE_FORMAT(NOW(), '%Y%m%d'), '%'))
  , #{cmpnyCd}
  , #{siteCd}
  , #{targetUserCd}
  , #{notiType}
  , 'PUSH'
  , #{title}
  , #{body}
  , #{dataPayload}
  , 'PENDING'
  , 0
  , #{dedupKey}
  , 'N'
  , #{insertNo}
  , NOW()
)
